public str getName()
{
    return fieldPName(SalesTable, MatchingAgreement);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Integer);
    SalesTable salesTable;
    while select MatchingAgreement from salesTable
        group by MatchingAgreement
    {
        ret.add(salesTable.MatchingAgreement);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(SalesTable, MatchingAgreement));
    qbr.value(queryValue(_value));
}
